        raise ValueError("Inputs must be two-dimensional matrices")
    if with_result.shape != call_only.shape or with_result.shape != no_call.shape:
        raise ValueError("Input shapes must match")
    if with_result.size == 0:
        raise ValueError("Inputs must not be empty")
    if not np.all(np.isfinite(with_result)) or not np.all(np.isfinite(call_only)) or not np.all(np.isfinite(no_call)):
