    if np.any(with_result > 0) or np.any(call_only > 0) or np.any(no_call > 0):
        raise ValueError("All input values must be nonpositive")
    if isinstance(tau_filter, bool):
        raise ValueError("Threshold must not be boolean")
    if not np.isfinite(tau_filter) or tau_filter < 0:
        raise ValueError("Threshold must be finite and nonnegative")
    # Compute margins
    m1 = with_result - no_call
    m2 = with_result - call_only
    per_token_min = np.minimum(m1, m2)
    margins = np.max(per_token_min, axis=1)
    keep = margins > tau_filter
    return keep, margins.astype(np.float64)
